'use strict';
// Every preset swatch must ship a complete token set, a swatch colour, an accessible name, a local-mcp enum
// entry, and the contrast pairs the light theme relies on (see --mynt-accent-ink in style.css). The 2026-11 palettes
// are generated by deriveTokens() in scripts/preload.js, so the CSS values must match that recipe.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const root = path.join(__dirname, '..');
const read = file => fs.readFileSync(path.join(root, file), 'utf8');
const html = read('index.html'), css = read('style.css');
const presets = [...html.matchAll(/<input\b[^>]*>/g)].map(m => m[0])
    .filter(tag => /\bclass="colorPlate"/.test(tag) && /\bname="color"/.test(tag) && /\btype="radio"/.test(tag))
    .map(tag => /\bvalue="([a-z]+)"/.exec(tag)[1]);

const EXPECTED = ['haze', 'mauve', 'midnight', 'sage', 'forest', 'ocean', 'latte', 'caramel', 'rose', 'graphite', 'pearl', 'ink'];
const RETIRED = ['red', 'yellow', 'green', 'cyan', 'blue', 'pink', 'purple', 'orange', 'brown', 'silver', 'peach', 'indigo',
    'teal', 'lime', 'amber', 'wine', 'magenta', 'slate', 'dark'];
assert.deepEqual(presets, EXPECTED, 'The 12 owner-chosen palettes, in order');
assert.match(html, /<input id="dfChecked" class="colorPlate" name="color" type="radio" checked value="haze">/, 'Haze is the default swatch');

// Run the real preload helpers against an empty profile.
const style = new Map(), storage = new Map();
const context = {
    window: { matchMedia: () => ({ matches: false }) },
    document: { documentElement: { style: { setProperty: (k, v) => style.set(k, v), removeProperty: k => style.delete(k) }, setAttribute() {}, toggleAttribute() {} } },
    localStorage: { getItem: k => storage.has(k) ? storage.get(k) : null, setItem: (k, v) => storage.set(k, String(v)), removeItem: k => storage.delete(k) }
};
vm.runInNewContext(read('scripts/preload.js'), context);
const helpers = context.window.ThemeHelpers;
assert.deepEqual(Object.keys(helpers.PALETTES), EXPECTED, 'preload.js lists the same palettes');
assert.deepEqual(Object.keys(helpers.LEGACY_PALETTES).sort(), [...RETIRED].sort(), 'Every retired swatch id has a migration target');
for (const [from, to] of Object.entries(helpers.LEGACY_PALETTES)) assert(EXPECTED.includes(to), `${from} migrates to a current palette`);
assert.equal(style.get('--bg-color-blue'), 'var(--bg-color-haze)', 'An empty profile paints haze before first paint');

const token = (name, color) => {
    const match = new RegExp(`--${name}-${color}:\\s*(#[0-9a-f]{6})\\s*;`, 'i').exec(css);
    assert(match, `style.css defines --${name}-${color}`);
    return match[1].toLowerCase();
};
const luminance = hex => [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16) / 255)
    .map(v => v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4)
    .reduce((sum, v, i) => sum + v * [0.2126, 0.7152, 0.0722][i], 0);
const ratio = (a, b) => { const x = luminance(a), y = luminance(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const mixBlack = (hex, keep) => '#' + [1, 3, 5].map(i => Math.round(parseInt(hex.slice(i, i + 2), 16) * keep).toString(16).padStart(2, '0')).join('');

const locales = { en: read('locales/en.js'), zh_TW: read('locales/zh_TW.js') };
const mcpRuntime = /const PALETTES=\[([^\]]+)\]/.exec(read('scripts/local-mcp-preferences.js'))[1].split(',').map(v => v.replace(/'/g, ''));
const mcpTool = JSON.parse(read('local-mcp/preferences-tools.json')).find(tool => tool.name === 'mynt_theme_update').inputSchema.properties.palette.enum;
assert.deepEqual(mcpRuntime, presets, 'local-mcp runtime palettes match the swatches');
assert.deepEqual(mcpTool, presets, 'Published local-mcp palette enum matches the swatches');
for (const retired of RETIRED) {
    for (const [lang, source] of Object.entries(locales)) assert(!source.includes(`"themeColor${retired[0].toUpperCase() + retired.slice(1)}":`), `${lang} drops the retired ${retired} name`);
}

// Review r1 #5: local MCP reads retired ids with the same table preload.js migrates with.
const mcpLegacy = /const LEGACY_PALETTES=(\{[^}]+\})/.exec(read('scripts/local-mcp-preferences.js'))[1];
assert.deepEqual(JSON.parse(JSON.stringify(vm.runInNewContext(`(${mcpLegacy})`))), JSON.parse(JSON.stringify(helpers.LEGACY_PALETTES)), 'local-mcp legacy table matches preload.js');
// Review r1 #8: nothing reads a retired palette token without a fixed fallback (blue is the active slot; silver and
// dark tokens are still defined).
const RETIRED_TOKEN = new RegExp(`var\\(--(?:bg-color|accentLightTint|darkerColor|darkColor|textColorDark|whitishColor)-(?:${RETIRED.filter(id => !['blue', 'silver', 'dark'].includes(id)).join('|')})\\)`);
for (const file of ['index.html', 'style.css', 'tools/languagesAnalysis.html', ...fs.readdirSync(path.join(root, 'styles')).map(name => `styles/${name}`),
    ...fs.readdirSync(path.join(root, 'scripts')).map(name => `scripts/${name}`)]) {
    assert(!RETIRED_TOKEN.test(read(file)), `${file} reads a retired palette token without a fallback`);
}
assert(!/'--bg-color-' \+/.test(read('scripts/quicklink-icons.js')), 'Quick-link badge colours no longer read retired per-palette tokens');
const NAMES = { zh_TW: ['霧霾藍', '莫蘭迪紫', '午夜藍', '鼠尾草綠', '森林綠', '海洋青', '奶茶棕', '焦糖棕', '乾燥玫瑰', '石墨灰', '珍珠灰', '極簡黑'] };
const report = [];
presets.forEach((color, index) => {
    const accent = helpers.PALETTES[color].toLowerCase();
    assert(new RegExp(`\\.colorsContainer input\\[value="${color}"\\]\\s*\\{\\s*background-color:\\s*${accent};`).test(css), `Swatch colour for ${color} is its accent`);
    const key = 'themeColor' + color[0].toUpperCase() + color.slice(1);
    for (const [lang, source] of Object.entries(locales)) assert(source.includes(`"${key}":`), `${lang} names the ${color} swatch`);
    assert(locales.zh_TW.includes(`"${key}": "${NAMES.zh_TW[index]}"`), `${color} uses the owner's zh_TW name`);
    const t = Object.fromEntries(['bg-color', 'accentLightTint', 'darkerColor', 'darkColor', 'textColorDark', 'whitishColor'].map(n => [n, token(n, color)]));
    assert.equal(t.darkColor, accent, `${color}: accent token is the owner's hex`);
    assert.equal(t.whitishColor, '#ffffff', `${color}: cards are white`);
    assert.deepEqual(t, Object.fromEntries(Object.entries(helpers.deriveTokens(helpers.PALETTES[color])).map(([k, v]) => [k, v.toLowerCase()])),
        `${color}: CSS tokens match deriveTokens()`);
    const ink = mixBlack(t.darkerColor, 0.7);
    const action = Math.max(...[t.textColorDark, '#ffffff', '#000000'].map(fg => ratio(t.darkerColor, fg)));
    const pairs = [['text on page', ratio(t.textColorDark, t['bg-color'])], ['text on side panel', ratio(t.textColorDark, t.accentLightTint)],
        ['text on card', ratio(t.textColorDark, t.whitishColor)], ['accent ink on tint', ratio(ink, t.accentLightTint)],
        ['white on accent ink', ratio(ink, '#ffffff')], ['action label', action],
        ['darkerColor on page', ratio(t.darkerColor, t['bg-color'])], ['darkerColor on tint', ratio(t.darkerColor, t.accentLightTint)],
        ['best label on accent', Math.max(...[t.textColorDark, '#ffffff', '#000000'].map(fg => ratio(t.darkColor, fg)))]];
    for (const [label, value] of pairs) assert(value >= 4.5, `${color}: ${label} ${value.toFixed(2)}:1`);
    report.push(`${color} ${Object.values(t).join(' ')} ` + pairs.map(([label, value]) => `${label}=${value.toFixed(2)}`).join(' '));
});
if (process.argv.includes('--report')) console.log(report.join('\n'));
console.log(`THEME_PALETTES_OK presets=${presets.length} retired=${RETIRED.length}`);
